import zlib
import struct
from typing import List, Tuple, Set, Optional, Dict

class IBLTCell:
    __slots__ = ('count', 'key_sum', 'value_sum')

    def __init__(self, count: int = 0, key_sum: int = 0, value_sum: bytes = b''):
        self.count = count
        self.key_sum = key_sum
        self.value_sum = value_sum

    def is_empty(self) -> bool:
        return self.count == 0 and self.key_sum == 0 and len(self.value_sum) == 0

    def clone(self) -> 'IBLTCell':
        return IBLTCell(self.count, self.key_sum, self.value_sum)

class InvertibleBloomLookupTable:
    def __init__(self, size: int = 80, num_hashes: int = 4, value_size: int = 32):
        self.size = size
        self.num_hashes = num_hashes
        self.value_size = value_size
        self.table: List[IBLTCell] = [IBLTCell(0, 0, b'\x00' * value_size) for _ in range(size)]

    def _hash_key(self, key: int) -> List[int]:
        indices = []
        b_key = key.to_bytes(8, 'big', signed=True) if isinstance(key, int) else str(key).encode('utf-8')
        for i in range(self.num_hashes):
            h_input = b_key + struct.pack('>I', i)
            h = zlib.crc32(h_input) & 0xFFFFFFFF
            indices.append(h % self.size)
        return indices

    def _pad_value(self, val: bytes) -> bytes:
        if len(val) < self.value_size:
            return val + b'\x00' * (self.value_size - len(val))
        return val[:self.value_size]

    def _xor_bytes(self, b1: bytes, b2: bytes) -> bytes:
        return bytes(x ^ y for x, y in zip(b1, b2))

    def insert(self, key: int, value: bytes):
        padded = self._pad_value(value)
        indices = self._hash_key(key)
        for idx in indices:
            cell = self.table[idx]
            cell.count += 1
            cell.key_sum ^= key
            cell.value_sum = self._xor_bytes(cell.value_sum, padded)

    def delete(self, key: int, value: bytes):
        padded = self._pad_value(value)
        indices = self._hash_key(key)
        for idx in indices:
            cell = self.table[idx]
            cell.count -= 1
            cell.key_sum ^= key
            cell.value_sum = self._xor_bytes(cell.value_sum, padded)

    def list_entries(self) -> Tuple[Set[Tuple[int, bytes]], Set[Tuple[int, bytes]], bool]:
        work_table = [cell.clone() for cell in self.table]
        added: Set[Tuple[int, bytes]] = set()
        removed: Set[Tuple[int, bytes]] = set()

        progress = True
        while progress:
            progress = False
            for i in range(self.size):
                cell = work_table[i]
                if cell.count == 1 or cell.count == -1:
                    if cell.key_sum != 0:
                        key = cell.key_sum
                        val = cell.value_sum

                        # Verify integrity by re-hashing
                        indices = self._hash_key(key)
                        valid = True
                        for idx in indices:
                            chk = work_table[idx]
                            if chk.count == 0:
                                valid = False
                                break

                        if valid:
                            entry = (key, val)
                            if cell.count == 1:
                                added.add(entry)
                                factor = 1
                            else:
                                removed.add(entry)
                                factor = -1

                            for idx in indices:
                                chk = work_table[idx]
                                chk.count -= factor
                                chk.key_sum ^= key
                                chk.value_sum = self._xor_bytes(chk.value_sum, val)
                            progress = True
                            break

        success = all(cell.is_empty() for cell in work_table)
        return added, removed, success

    def subtract(self, other: 'InvertibleBloomLookupTable') -> 'InvertibleBloomLookupTable':
        if self.size != other.size or self.num_hashes != other.num_hashes:
            raise ValueError("IBLT dimensions must match for subtraction")
        result = InvertibleBloomLookupTable(self.size, self.num_hashes, self.value_size)
        for i in range(self.size):
            c1 = self.table[i]
            c2 = other.table[i]
            result.table[i] = IBLTCell(
                count=c1.count - c2.count,
                key_sum=c1.key_sum ^ c2.key_sum,
                value_sum=self._xor_bytes(c1.value_sum, c2.value_sum)
            )
        return result

    def serialize(self) -> dict:
        return {
            "size": self.size,
            "num_hashes": self.num_hashes,
            "value_size": self.value_size,
            "cells": [
                {"count": c.count, "key_sum": c.key_sum, "value_sum": c.value_sum.hex()}
                for c in self.table
            ]
        }

    @classmethod
    def deserialize(cls, data: dict) -> 'InvertibleBloomLookupTable':
        iblt = cls(size=data["size"], num_hashes=data["num_hashes"], value_size=data["value_size"])
        iblt.table = [
            IBLTCell(count=c["count"], key_sum=c["key_sum"], value_sum=bytes.fromhex(c["value_sum"]))
            for c in data["cells"]
        ]
        return iblt

from typing import Set, Tuple, Dict, Any, Optional
from gossipmesh.p2p.reconciliation.iblt import InvertibleBloomLookupTable

class IBLTReconciliationProtocol:
    def __init__(self, size: int = 80, num_hashes: int = 4, value_size: int = 32):
        self.size = size
        self.num_hashes = num_hashes
        self.value_size = value_size

    def create_iblt(self, inventory: Dict[int, bytes]) -> InvertibleBloomLookupTable:
        iblt = InvertibleBloomLookupTable(self.size, self.num_hashes, self.value_size)
        for k, v in inventory.items():
            iblt.insert(k, v)
        return iblt

    def reconcile(
        self, 
        local_inventory: Dict[int, bytes], 
        remote_iblt_data: dict
    ) -> Tuple[Set[Tuple[int, bytes]], Set[Tuple[int, bytes]], bool]:
        local_iblt = self.create_iblt(local_inventory)
        remote_iblt = InvertibleBloomLookupTable.deserialize(remote_iblt_data)

        diff_iblt = local_iblt.subtract(remote_iblt)
        added, removed, success = diff_iblt.list_entries()
        return added, removed, success

    def fallback_full_sync(self, local_inventory: Dict[int, bytes], remote_keys: List[int]) -> Dict[int, bytes]:
        missing = {}
        remote_set = set(remote_keys)
        for k, v in local_inventory.items():
            if k not in remote_set:
                missing[k] = v
        return missing

import unittest
from gossipmesh.p2p.reconciliation.iblt import InvertibleBloomLookupTable
from gossipmesh.p2p.reconciliation.protocol import IBLTReconciliationProtocol

class TestIBLTReconciliation(unittest.TestCase):
    def setUp(self):
        self.size = 60
        self.num_hashes = 3
        self.value_size = 16
        self.protocol = IBLTReconciliationProtocol(size=self.size, num_hashes=self.num_hashes, value_size=self.value_size)

    def test_iblt_basic_insertion_and_recovery(self):
        iblt = InvertibleBloomLookupTable(size=self.size, num_hashes=self.num_hashes, value_size=self.value_size)
        items = {
            101: b'payload_one',
            102: b'payload_two',
            103: b'payload_three'
        }
        for k, v in items.items():
            iblt.insert(k, v)

        added, removed, success = iblt.list_entries()
        self.assertTrue(success)
        self.assertEqual(len(added), 3)
        self.assertEqual(len(removed), 0)
        recovered_keys = {item[0] for item in added}
        self.assertEqual(recovered_keys, set(items.keys()))

    def test_iblt_reconciliation_protocol(self):
        node_a_inv = {
            1: b'alpha',
            2: b'beta',
            3: b'gamma'
        }
        node_b_inv = {
            2: b'beta',
            3: b'gamma',
            4: b'delta'
        }

        iblt_b = self.protocol.create_iblt(node_b_inv)
        added, removed, success = self.protocol.reconcile(node_a_inv, iblt_b.serialize())

        self.assertTrue(success)
        # Node A has key 1 (missing in B -> added relative to B), Node A lacks key 4 (removed relative to B)
        added_keys = {item[0] for item in added}
        removed_keys = {item[0] for item in removed}

        self.assertIn(1, added_keys)
        self.assertIn(4, removed_keys)

    def test_iblt_collision_fallback(self):
        # Force a collision by creating a very small IBLT with many conflicting elements
        iblt = InvertibleBloomLookupTable(size=2, num_hashes=4, value_size=8)
        for i in range(50):
            iblt.insert(i, b'data')

        _, _, success = iblt.list_entries()
        # With size=2 and 50 elements, decoding should fail and trigger fallback
        self.assertFalse(success)

    def_protocol_fallback = test_fallback_full_sync = lambda self: None
    def test_fallback_sync(self):
        local_inv = {10: b'x', 20: b'y'}
        remote_keys = [20, 30]
        missing = self.protocol.fallback_full_sync(local_inv, remote_keys)
        self.assertEqual(missing, {10: b'x'})

if __name__ == '__main__':
    unittest.main()
